  warn(_message: string, fields: object) {
    fieldsSeen.push(fields)
    throw failure
  }
}
const probe = createRpcLogProbe(logger, {
  stages: ['message'],
  capture: ['message'],
  slowMs: 0,
  redact: () => masked,
  onError: (error) => {
