  }
})
const [left, right] = createMemoryTransportPair()
const server = await createEndpoint({
  id: 'server',
  transport: right,
  middlewares: [connect()],
  provider: { echo: (context) => context.success(context.data) }
})
const client = await createEndpoint({
  id: 'client',
  transport: left,
  middlewares: [connect(), probePlugin(probe)]
})
try {
